import React, { useState } from 'react';
import { Toast } from './Toast';
import { MessageList } from './MessageList';
import { ClearButton } from './ClearButton';

const App: React.FC = () => {
  const [toasts, setToasts] = useState<{ id: string; message: string; type: 'success' | 'warning' | 'error' }[]>([]);
  const [isToastVisible, setIsToastVisible] = useState<boolean>(false);

  const showToast = (type: 'success' | 'warning' | 'error', message: string) => {
    const id = `toast-${Date.now()}`;
    setToasts((prev) => [
      ...prev,
      { id, message, type },
    ]);
    setIsToastVisible(true);

    // Auto-hide after 3 seconds
    setTimeout(() => {
      setIsToastVisible(false);
    }, 3000);
  };

  const clearAll = () => {
    setToasts([]);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-start p-6">
      <div className="w-full max-w-md bg-white rounded-lg shadow-md p-6 space-y-6">
        <h1 className="text-2xl font-bold text-gray-800">Notification Center</h1>

        <div className="flex flex-wrap gap-3">
          <button
            onClick={() => showToast('success', 'Operation completed successfully!')}
            className="px-4 py-2 bg-green-500 text-white rounded-md hover:bg-green-600 transition-colors"
          >
            Success
          </button>
          <button
            onClick={() => showToast('warning', 'This action may have unintended consequences!')}
            className="px-4 py-2 bg-yellow-500 text-white rounded-md hover:bg-yellow-600 transition-colors"
          >
            Warning
          </button>
          <button
            onClick={() => showToast('error', 'Something went wrong! Please try again later.')}
            className="px-4 py-2 bg-red-500 text-white rounded-md hover:bg-red-600 transition-colors"
          >
            Error
          </button>
        </div>

        <div className="mt-6">
          <MessageList toasts={toasts} />
        </div>

        <ClearButton onClick={clearAll} />
      </div>
    </div>
  );
};

export default App;
```

