import React from 'react';
import { Toast } from './Toast';

interface MessageListProps {
  toasts: Array<{ id: string; message: string; type: 'success' | 'warning' | 'error' }>;
}

const MessageList: React.FC<MessageListProps> = ({ toasts }) => {
  const lastFive = toasts.slice(-5);
  return (
    <div className="border-t pt-4 mt-4">
      <h2 className="text-sm font-semibold text-gray-700 mb-2">Recent Messages</h2>
      {lastFive.length === 0 ? (
        <p className="text-sm text-gray-500">No messages yet.</p>
      ) : (
        <div className="space-y-2">
          {lastFive.map((toast) => (
            <Toast
              key={toast.id}
              message={toast.message}
              type={toast.type}
              onClose={() => {}}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default MessageList;
